sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var bulkSysId = current.bulk_id.sys_id + '';

        if (current.trade_task_type.indexOf('GHSS Handler') > -1) { //correct
            if (!hasActiveMakerTask(bulkSysId)) {
                updateBulkCount('GHSS Handler');
            }
        } else if (current.trade_task_type == 'Maker') {
            updateBulkCountForMaker(bulkSysId);
        } else if (current.trade_task_type == 'Checker') {
            updateBulkCount('Checker');
        }

        function hasActiveMakerTask(bulkSysId) {
            var gr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            gr.addEncodedQuery('active=true^trade_task_type=Maker^stateIN1,2^bulk_id.sys_id=' + bulkSysId);
            gr.query();
            return gr.hasNext();
        }

        function updateBulkCount(tradeTaskType) {
            var finalCount = 0;
            var gr = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
            gr.addAggregate('COUNT', 'trade_task_type');
            gr.groupBy('trade_task_type');
            gr.addEncodedQuery('active=true^trade_task_typeSTARTSWITH' + tradeTaskType +
                '^bulk_idISNOTEMPTY^bulk_id.sys_id=' + current.bulk_id.sys_id);
            gr.query();

            while (gr.next()) {
                finalCount = gr.getAggregate('COUNT', 'trade_task_type');
            }

            var updateBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            updateBulk.get(current.bulk_id.sys_id);
            updateBulk.active_trade_count = finalCount ? parseInt(finalCount, 10) : '';
            updateBulk.update();
        }

        function updateBulkCountForMaker(bulkSysId) {
            var makerCount = countTasks(
                'active=true^bulk_idISNOTEMPTY^bulk_id.sys_id=' + bulkSysId + '^trade_task_type=Maker'
            );

            var amendRecreatedCheckerCount = countTasks(
                'active=true^bulk_idISNOTEMPTY^bulk_id.sys_id=' + bulkSysId +
                '^trade_task_type=Checker^amend_checker_decision=Amend_Recreated'
            );

            var finalCount = makerCount + amendRecreatedCheckerCount;

            var updateBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (updateBulk.get(bulkSysId)) {
                updateBulk.active_trade_count = finalCount; 
                updateBulk.update();
            }
        }

        function countTasks(encodedQuery) {
            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
            ga.addEncodedQuery(encodedQuery);
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                return parseInt(ga.getAggregate('COUNT'), 10) || 0;
            }
            return 0;
        }

    } catch (e) {
        gs.info('error in BR updting ATC: ' + e.message);
    }
})(current, previous);
